\echo '=== CAT1 category tree withCounts (180 categories x bounded 1001)'
EXPLAIN (ANALYZE, BUFFERS) SELECT c.id, (SELECT count(*) FROM (SELECT 1 FROM catalog_product p WHERE p.primary_category_id = c.id UNION ALL SELECT 1 FROM catalog_product_category pc WHERE pc.category_id = c.id LIMIT 1001) t) AS products FROM catalog_category c;
\echo '=== PS1 product list summaries for 25 ids'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.slug, p.status, p.updated_at, c.id AS category_id, c.name AS category_name, (SELECT COUNT(*) FROM catalog_product_variant v WHERE v.product_id = p.id) AS variant_count, p.images -> 0 ->> 'key' AS image_key, p.images -> 0 ->> 'alt' AS image_alt FROM catalog_product p JOIN catalog_category c ON c.id = p.primary_category_id WHERE p.id = ANY(CAST('{b31d8f56-5431-58b8-9249-d89e85e95ec5,b996a759-a5f7-5c63-9314-cf158e29175c,a0748cd5-7bf5-5219-9f31-64ed3ded6872,98504e4f-2eee-59e4-9164-1b0cfae62cd4,558464ec-0622-5acc-aff5-0c025b0be61a,c90c2667-6f88-5d79-90e5-e8ee1e9e5e19,9c8d5672-2dd8-5690-ad42-daa9f0cb31c4,6ae68872-87fb-50ac-a64a-af149dd95e8b,5eeec4d9-b20b-51b7-abeb-5e4ade0468bf,1b3d8f45-e217-5556-bd5e-8f780d6cd01e,3ea9da66-4828-59df-bf13-e5b1540fc089,630bbeb9-fd90-5e3f-97c6-70eddba07747,1200c21d-b94b-5043-8fe6-e1878b43925e,b5b5d506-5f5a-59ce-b0dd-c56740f3393f,693eefc8-e02c-5605-821e-c8ac71328214,158685ea-ea9e-5887-ad7a-e50be73b0543,951199aa-fd20-5da3-8ce4-131d9ac53395,903ba195-2341-5f0a-94f4-bc1f1ad59441,6de99f44-565a-56ea-88e1-48e97ff8f9ac,2a27fbb8-5215-5379-823d-7a7f9c8b46ca,98a87ecf-23a2-593b-a108-6060633d2a50,73c5527f-775a-5b98-8ddf-757aa063036c,066aeb78-5b98-5a57-a3bc-0b53a2116aa0,874130a1-54d9-53e0-8178-84fd0772f49a,eadda1d7-d96d-569e-83b9-ce65403f3b6d}' AS uuid[]));
